import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC04%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E7%B3%BB%E7%BB%9F%E7%AE%A1%E7%90%86/","title":"第04章 信息系统管理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第04章 信息系统管理/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第04章-信息系统管理" tabindex="-1"><a class="header-anchor" href="#第04章-信息系统管理"><span>第04章 信息系统管理</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍信息系统管理的概念、IT服务管理以及信息安全管理的相关知识。</p><p><strong>重点知识点：</strong></p><ul><li>信息系统管理的内容</li><li>IT服务管理框架</li><li>ITIL服务生命周期</li><li>信息安全管理体系</li></ul><hr><h2 id="_4-1-系统管理概述" tabindex="-1"><a class="header-anchor" href="#_4-1-系统管理概述"><span>4.1 系统管理概述</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>信息系统管理是指对信息系统的规划、开发、实施、运维和优化进行全面管理。</p><h3 id="管理内容" tabindex="-1"><a class="header-anchor" href="#管理内容"><span>管理内容</span></a></h3><ul><li>硬件管理</li><li>软件管理</li><li>数据管理</li><li>用户管理</li><li>安全管理</li></ul><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>信息系统管理的主要内容</li><li>系统管理的目标</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>软硬数用安，系统管理全</p><hr><h2 id="_4-2-it服务管理" tabindex="-1"><a class="header-anchor" href="#_4-2-it服务管理"><span>4.2 IT服务管理</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>IT服务管理是指通过整合IT服务与业务需求，提供高质量的IT服务。</p><h3 id="itil框架" tabindex="-1"><a class="header-anchor" href="#itil框架"><span>ITIL框架</span></a></h3><ul><li>服务战略</li><li>服务设计</li><li>服务过渡</li><li>服务运营</li><li>持续服务改进</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>ITIL的五大服务生命周期</li><li>IT服务管理的核心流程</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>战略设计过渡运营持续改</p><hr><h2 id="_4-3-信息安全管理" tabindex="-1"><a class="header-anchor" href="#_4-3-信息安全管理"><span>4.3 信息安全管理</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>信息安全管理是指保护信息资产的机密性、完整性和可用性。</p><h3 id="安全要素" tabindex="-1"><a class="header-anchor" href="#安全要素"><span>安全要素</span></a></h3><ul><li>机密性：防止未授权访问</li><li>完整性：防止数据篡改</li><li>可用性：确保系统正常运行</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>信息安全三要素</li><li>安全管理措施</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>机密完整可用，安全三要素</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};